import { edit_delete_events } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import trashIcon from "@/assets/trash.png";
export default {
  props: {
    eventDelete: Boolean,
    eventInfo: Object
  },
  data() {
    return {
      loading: false,
      trashIcon: trashIcon
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_event() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_delete_events, {
          input: {
            action_type: "DELETE",
            event_id: this.eventInfo.event_id
          }
        }));
        var response = JSON.parse(result.data.edit_delete_events);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
